def execute_ssh_command(connection, command, **_extra):
    import json, os, datetime, re, time, base64, hashlib, subprocess
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0230000" if __import__("os").path.isdir("./environment_mix/0230000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(connection, dict):
        return _err("VALIDATION_ERROR", "connection must be an object")
    if not isinstance(command, str) or not (1 <= len(command) <= 16384):
        return _err("VALIDATION_ERROR", "command must be a non-empty string up to 16384 chars")

    host = connection.get("host")
    username = connection.get("username")
    port = connection.get("port", 22)

    password = connection.get("password", None)
    private_key = connection.get("privateKey", None)

    if not isinstance(host, str) or not (1 <= len(host) <= 255):
        return _err("VALIDATION_ERROR", "connection.host must be a non-empty string of length 1..255")
    if not isinstance(username, str) or not (1 <= len(username) <= 128):
        return _err("VALIDATION_ERROR", "connection.username must be a non-empty string of length 1..128")

    # Port validation: tool schema says number; accept int-like floats
    if isinstance(port, bool) or not isinstance(port, (int, float)) or int(port) != port:
        return _err("VALIDATION_ERROR", "connection.port must be an integer")
    port = int(port)
    if not (1 <= port <= 65535):
        return _err("VALIDATION_ERROR", "connection.port must be between 1 and 65535")

    password_present = isinstance(password, str) and len(password) > 0
    private_key_present = isinstance(private_key, str) and len(private_key) > 0

    if password_present and private_key_present:
        auth_provided = "both"
    elif password_present:
        auth_provided = "password"
    elif private_key_present:
        auth_provided = "private_key"
    else:
        auth_provided = "none"

    # Load store
    targets = _load("ssh_targets.json")
    creds = _load("ssh_credentials.json")
    conns = _load("ssh_connections.json")
    execs = _load("ssh_command_executions.json")
    rate_rules = _load("ssh_rate_limits.json")

    # Resolve target by (host,port)
    target = None
    for t in targets:
        if t.get("host") == host and t.get("port") == port:
            target = t
            break
    if target is None:
        # No target row: treat as missing reference
        # Still record nothing (no usage/audit collection declared).
        return _err("NOT_FOUND", "No ssh target found for host/port", host=host, port=port)

    # Resolve optional saved connection profile if needed
    resolved_connection = None
    resolved_credential = None
    connection_id = None

    if auth_provided == "none":
        # must resolve by (host,port,username) to an active profile supplying active credentials
        for c in conns:
            if c.get("status") != "active":
                continue
            if c.get("target_id") != target.get("id"):
                continue
            cred = next((cr for cr in creds if cr.get("id") == c.get("credential_id")), None)
            if cred is None or cred.get("status") != "active":
                continue
            # profile doesn't store username; must match by credential.username
            if cred.get("username") != username:
                continue
            resolved_connection = c
            resolved_credential = cred
            connection_id = c.get("id")
            break
        if resolved_connection is None:
            return _err(
                "VALIDATION_ERROR",
                "No credentials provided and no active saved connection profile could be resolved for (host,port,username)."
            )
    else:
        # credentials provided inline; optionally associate to a saved connection if exists with matching target and username and active
        for c in conns:
            if c.get("status") != "active":
                continue
            if c.get("target_id") != target.get("id"):
                continue
            cred = next((cr for cr in creds if cr.get("id") == c.get("credential_id")), None)
            if cred is None or cred.get("status") != "active":
                continue
            if cred.get("username") != username:
                continue
            resolved_connection = c
            resolved_credential = cred
            connection_id = c.get("id")
            break

    # Enforce lifecycle: target active and any resolved credential active
    if target.get("status") != "active":
        # Record a failed execution attempt (accepted then failed) per policy? Rule only mandates record for command policy rejects.
        return _err("UNAUTHORIZED", "Target is not active")
    if resolved_credential is not None and resolved_credential.get("status") != "active":
        return _err("UNAUTHORIZED", "Credential is not active")

    # Rate limit enforcement (counts requested_at within window for active rules)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = _parse_dt(now) or datetime.datetime.utcnow().replace(microsecond=0)

    applicable_rules = []
    for r in rate_rules:
        if r.get("status") != "active":
            continue
        if r.get("host") != host:
            continue
        ru = r.get("username")
        if ru is not None and ru != username:
            continue
        applicable_rules.append(r)

    for r in applicable_rules:
        window_seconds = r.get("window_seconds")
        max_exec = r.get("max_executions")
        if not isinstance(window_seconds, int) or not (1 <= window_seconds <= 86400):
            continue
        if not isinstance(max_exec, int) or not (1 <= max_exec <= 100000):
            continue
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        count = 0
        for e in execs:
            if e.get("host") != host:
                continue
            if r.get("username") is not None and e.get("username") != username:
                continue
            e_dt = _parse_dt(e.get("requested_at"))
            if e_dt is None:
                continue
            if e_dt >= cutoff:
                count += 1
        if count >= max_exec:
            return _err("RATE_LIMIT", "Rate limit exceeded", host=host, username=username, window_seconds=window_seconds, max_executions=max_exec)

    # Command policy enforcement: if allowed_command_regex set and active target, must match else reject and record failed execution
    allowed_re = target.get("allowed_command_regex")
    if allowed_re is not None:
        if not isinstance(allowed_re, str) or allowed_re == "":
            # Treat invalid regex configuration as conflict
            return _err("CONFLICT", "Target command policy is misconfigured")
        try:
            if re.search(allowed_re, command) is None:
                # record failed execution
                def _new_id(prefix):
                    raw = f"{prefix}_{datetime.datetime.utcnow().timestamp()}_{os.getpid()}_{len(execs)}"
                    h = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]
                    return f"{prefix}_{h}"
                eid = _new_id("exec")
                row = {
                    "id": eid,
                    "connection_id": connection_id,
                    "host": host,
                    "port": port,
                    "username": username,
                    "auth_provided": auth_provided,
                    "password_present": bool(password_present),
                    "private_key_present": bool(private_key_present),
                    "command": command,
                    "status": "failed",
                    "requested_at": now,
                    "started_at": now,
                    "finished_at": now,
                    "timeout_seconds": 60,
                    "exit_code": None,
                    "stdout": None,
                    "stderr": None,
                    "stdout_truncated": False,
                    "stderr_truncated": False,
                    "error_message": "Command rejected by policy",
                    "created_at": now,
                    "updated_at": now,
                }
                execs.append(row)
                _save("ssh_command_executions.json", execs)
                return {"execution": row}
        except re.error:
            return _err("CONFLICT", "Target command policy regex is invalid")

    # Create execution row: queued -> running -> terminal
    # Apply server-side timeout (default 60s)
    timeout_seconds = 60
    if not (1 <= timeout_seconds <= 3600):
        timeout_seconds = 60

    def _new_id(prefix):
        raw = f"{prefix}_{datetime.datetime.utcnow().timestamp()}_{os.getpid()}_{len(execs)}"
        h = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    eid = _new_id("exec")
    row = {
        "id": eid,
        "connection_id": connection_id,
        "host": host,
        "port": port,
        "username": username,
        "auth_provided": auth_provided,
        "password_present": bool(password_present),
        "private_key_present": bool(private_key_present),
        "command": command,
        "status": "queued",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "timeout_seconds": timeout_seconds,
        "exit_code": None,
        "stdout": None,
        "stderr": None,
        "stdout_truncated": False,
        "stderr_truncated": False,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    execs.append(row)
    _save("ssh_command_executions.json", execs)

    # Transition to running
    start_ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row["status"] = "running"
    row["started_at"] = start_ts
    row["updated_at"] = start_ts
    _save("ssh_command_executions.json", execs)

    # Execute locally (offline approximation) with timeout; truncate outputs to 64KB
    MAX_OUT = 65536

    def _truncate(s):
        if s is None:
            return None, False
        if len(s) <= MAX_OUT:
            return s, False
        return s[:MAX_OUT], True

    terminal_status = "succeeded"
    exit_code = 0
    stdout_s = ""
    stderr_s = ""
    err_msg = None

    try:
        # This is a local execution surrogate; real SSH is not performed in this offline environment.
        cp = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout_seconds
        )
        exit_code = cp.returncode
        stdout_s = cp.stdout if isinstance(cp.stdout, str) else ""
        stderr_s = cp.stderr if isinstance(cp.stderr, str) else ""
        terminal_status = "succeeded" if exit_code == 0 else "failed"
        if terminal_status == "failed":
            err_msg = "Command failed"
    except subprocess.TimeoutExpired:
        terminal_status = "timed_out"
        exit_code = None
        err_msg = "Execution timed out"
    except Exception:
        terminal_status = "failed"
        exit_code = None
        err_msg = "Execution failed"

    stdout_s, stdout_tr = _truncate(stdout_s)
    stderr_s, stderr_tr = _truncate(stderr_s)

    finish_ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row["status"] = terminal_status
    row["finished_at"] = finish_ts
    row["updated_at"] = finish_ts
    row["stdout"] = stdout_s
    row["stderr"] = stderr_s
    row["stdout_truncated"] = bool(stdout_tr)
    row["stderr_truncated"] = bool(stderr_tr)
    row["error_message"] = err_msg
    if terminal_status in ("succeeded", "failed"):
        row["exit_code"] = exit_code
    else:
        row["exit_code"] = None

    # update last_used_at for saved connection if we resolved an active one and succeeded
    if connection_id is not None and terminal_status == "succeeded":
        for c in conns:
            if c.get("id") == connection_id:
                c["last_used_at"] = finish_ts
                c["updated_at"] = finish_ts
                break
        _save("ssh_connections.json", conns)

    _save("ssh_command_executions.json", execs)

    return {"execution": row}

def list_ssh_command_executions(connection_id=None, host=None, username=None, status=None, requested_from=None, requested_to=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0230000" if __import__("os").path.isdir("./environment_mix/0230000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 string")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 timestamp")

    # Validate filters
    if connection_id is not None and not isinstance(connection_id, str):
        return _err("VALIDATION_ERROR", "connection_id must be a string")
    if host is not None and not isinstance(host, str):
        return _err("VALIDATION_ERROR", "host must be a string")
    if username is not None and not isinstance(username, str):
        return _err("VALIDATION_ERROR", "username must be a string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("queued", "running", "succeeded", "failed", "timed_out", "cancelled"):
            return _err("VALIDATION_ERROR", "status is invalid")
    if limit is None:
        limit = 50
    if isinstance(limit, bool) or not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    try:
        dt_from = _parse_dt(requested_from, "requested_from")
        dt_to = _parse_dt(requested_to, "requested_to")
    except ValueError as ve:
        return _err("VALIDATION_ERROR", str(ve))

    # Cursor: base64("offset:<n>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    rows = _load("ssh_command_executions.json")

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Filter
    out = []
    for r in rows:
        if connection_id is not None and r.get("connection_id") != connection_id:
            continue
        if host is not None and r.get("host") != host:
            continue
        if username is not None and r.get("username") != username:
            continue
        if status is not None and r.get("status") != status:
            continue
        rdt = _dt(r.get("requested_at"))
        if dt_from is not None and (rdt is None or rdt < dt_from):
            continue
        if dt_to is not None and (rdt is None or rdt > dt_to):
            continue
        out.append(r)

    # Sort reverse-chronological by requested_at then id
    out.sort(key=lambda r: (r.get("requested_at") or "", r.get("id") or ""), reverse=True)

    total = len(out)
    page = out[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    return {
        "executions": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_ssh_command_execution(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0230000" if __import__("os").path.isdir("./environment_mix/0230000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status_code, execution_id=None):
        # Best-effort: only if collection exists (list or {"rows":[...]})
        log = _load("ssh_request_logs.json")
        if isinstance(log, dict) and isinstance(log.get("rows"), list):
            log_rows = log["rows"]
            shape = "dict"
        elif isinstance(log, list):
            log_rows = log
            shape = "list"
        else:
            return
        row = {
            "id": "ssh_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_ssh_command_execution",
            "status": status_code,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if execution_id:
            row["execution_id"] = execution_id
        log_rows.append(row)
        _save("ssh_request_logs.json", {"rows": log_rows} if shape == "dict" else log_rows)

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _append_log("validation_error")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # Fetch
    data = _load("ssh_command_executions.json")
    rows = data.get("rows", []) if isinstance(data, dict) else (data if isinstance(data, list) else [])
    found = None
    for r in rows:
        if isinstance(r, dict) and r.get("id") == id:
            found = r
            break

    if found is None:
        _append_log("not_found", execution_id=id)
        return _err("NOT_FOUND", "ssh_command_execution not found", id=id)

    _append_log("succeeded", execution_id=id)
    return {"execution": found}

def cancel_ssh_command_execution(id, reason=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0230000" if __import__("os").path.isdir("./environment_mix/0230000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status_code, execution_id=None):
        log = _load("ssh_request_logs.json")
        if isinstance(log, dict) and isinstance(log.get("rows"), list):
            log_rows = log["rows"]
            shape = "dict"
        elif isinstance(log, list):
            log_rows = log
            shape = "list"
        else:
            return
        row = {
            "id": "ssh_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "cancel_ssh_command_execution",
            "status": status_code,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if execution_id:
            row["execution_id"] = execution_id
        log_rows.append(row)
        _save("ssh_request_logs.json", {"rows": log_rows} if shape == "dict" else log_rows)

    def _sanitize_reason(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        s = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        # keep it short and log-safe
        return s[:512]

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _append_log("validation_error")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _append_log("validation_error", execution_id=id)
        return _err("VALIDATION_ERROR", "reason must be a string")

    # Load executions
    data = _load("ssh_command_executions.json")
    rows = data.get("rows", []) if isinstance(data, dict) else (data if isinstance(data, list) else [])
    if not isinstance(rows, list):
        _append_log("error", execution_id=id)
        return _err("VALIDATION_ERROR", "datastore format invalid for ssh_command_executions")

    idx = None
    for i, r in enumerate(rows):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            break

    if idx is None:
        _append_log("not_found", execution_id=id)
        return _err("NOT_FOUND", "ssh_command_execution not found", id=id)

    exec_row = rows[idx]
    cur = exec_row.get("status")

    terminal = ("succeeded", "failed", "timed_out", "cancelled")
    cancellable = ("queued", "running")
    if cur in terminal:
        _append_log("invalid_transition", execution_id=id)
        return _err("INVALID_TRANSITION", "execution is already terminal and cannot be cancelled", id=id, status=cur)
    if cur not in cancellable:
        _append_log("invalid_transition", execution_id=id)
        return _err("INVALID_TRANSITION", "execution status cannot transition to cancelled", id=id, status=cur)

    # Apply transition
    now = _now()
    exec_row["status"] = "cancelled"
    exec_row["finished_at"] = now
    exec_row["updated_at"] = now
    # started_at remains as-is; requested_at remains as-is
    # exit_code can remain null; enforce rule: only terminal may have exit_code (we're terminal now), don't set it.
    sanitized = _sanitize_reason(reason)
    exec_row["error_message"] = sanitized or "cancelled by client request"

    rows[idx] = exec_row
    _save("ssh_command_executions.json", {"rows": rows} if isinstance(data, dict) else rows)

    _append_log("succeeded", execution_id=id)
    return {"execution": exec_row}

def list_ssh_targets(status=None, host=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0230000" if __import__("os").path.isdir("./environment_mix/0230000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _decode_cursor(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            return _err("VALIDATION_ERROR", "Invalid status. Must be 'active' or 'disabled'.", field="status")
    if host is not None and not isinstance(host, str):
        return _err("VALIDATION_ERROR", "Invalid host. Must be a string.", field="host")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Invalid limit. Must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit. Must be between 1 and 200.", field="limit")

    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "Invalid cursor. Must be a non-empty string.", field="cursor")
        cobj = _decode_cursor(cursor)
        if not cobj or cobj.get("v") != 1 or "after" not in cobj:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        start_after = cobj.get("after")
        if start_after is not None and not isinstance(start_after, str):
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Load data
    t0 = datetime.datetime.utcnow()
    targets = _load("ssh_targets.json")
    if not isinstance(targets, list):
        targets = []

    # Filter
    filtered = []
    for r in targets:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if host is not None and r.get("host") != host:
            continue
        filtered.append(r)

    # Sort by (created_at, id) ascending for stable pagination
    def _k(r):
        ca = r.get("created_at") or ""
        rid = r.get("id") or ""
        return (ca, rid)

    filtered.sort(key=_k)

    # Apply cursor
    if start_after:
        # start_after is an id; skip until strictly greater than that id within same sort order is ambiguous.
        # We'll interpret as "start after id" in the sorted list by id tie-breaker and ignoring created_at mismatches.
        # If multiple have same id (should not), still fine.
        passed = False
        page_candidates = []
        for r in filtered:
            if passed:
                page_candidates.append(r)
            else:
                if r.get("id") == start_after:
                    passed = True
        # If cursor id not found, treat as validation error (opaque but must be from previous call)
        if not passed:
            # Record call before returning
            reqlog = _load("ssh_request_log.json")
            if not isinstance(reqlog, list):
                reqlog = []
            latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            reqlog.append({
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("utf-8").rstrip("="),
                "endpoint": "list_ssh_targets",
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "timestamp": _now(),
                "latency_ms": latency_ms
            })
            _save("ssh_request_log.json", reqlog)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        filtered = page_candidates

    # Page
    page = filtered[:limit]
    has_more = len(filtered) > limit
    next_cursor = None
    if has_more and page:
        next_cursor = _encode_cursor({"v": 1, "after": page[-1].get("id")})

    # Record call (best-effort; create file if missing)
    reqlog = _load("ssh_request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []
    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    reqlog.append({
        "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("utf-8").rstrip("="),
        "endpoint": "list_ssh_targets",
        "status": "ok",
        "timestamp": _now(),
        "latency_ms": latency_ms
    })
    _save("ssh_request_log.json", reqlog)

    return {
        "data": page,
        "meta": {
            "total": len(filtered) if cursor is None else None,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def upsert_ssh_target(host, id=None, port=None, display_name=None, status=None, allowed_command_regex=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0230000" if __import__("os").path.isdir("./environment_mix/0230000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return prefix + "_" + base64.urlsafe_b64encode(os.urandom(12)).decode("utf-8").rstrip("=")

    def _is_nonempty_str(x):
        return isinstance(x, str) and len(x) > 0

    # Validate inputs
    if not _is_nonempty_str(host):
        return _err("VALIDATION_ERROR", "Invalid host. Must be a non-empty string.", field="host")
    if len(host) < 1 or len(host) > 255:
        return _err("VALIDATION_ERROR", "Invalid host length. Must be between 1 and 255.", field="host")

    if id is not None and not isinstance(id, str):
        return _err("VALIDATION_ERROR", "Invalid id. Must be a string.", field="id")

    if port is None:
        port = 22
    if not isinstance(port, int):
        return _err("VALIDATION_ERROR", "Invalid port. Must be an integer.", field="port")
    if port < 1 or port > 65535:
        return _err("VALIDATION_ERROR", "Invalid port. Must be between 1 and 65535.", field="port")

    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "Invalid display_name. Must be a string.", field="display_name")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            return _err("VALIDATION_ERROR", "Invalid status. Must be 'active' or 'disabled'.", field="status")

    if allowed_command_regex is not None:
        if not isinstance(allowed_command_regex, str):
            return _err("VALIDATION_ERROR", "Invalid allowed_command_regex. Must be a string.", field="allowed_command_regex")
        # Validate regex syntax
        try:
            re.compile(allowed_command_regex)
        except re.error as e:
            return _err("VALIDATION_ERROR", "Invalid allowed_command_regex syntax.", field="allowed_command_regex", details=str(e))

    t0 = datetime.datetime.utcnow()
    targets = _load("ssh_targets.json")
    if not isinstance(targets, list):
        targets = []

    now = _now()

    # Find existing
    existing = None
    existing_idx = None
    if id is not None:
        for i, r in enumerate(targets):
            if isinstance(r, dict) and r.get("id") == id:
                existing = r
                existing_idx = i
                break
        if existing is None:
            # Record request log
            reqlog = _load("ssh_request_log.json")
            if not isinstance(reqlog, list):
                reqlog = []
            latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            reqlog.append({
                "id": _gen_id("req"),
                "endpoint": "upsert_ssh_target",
                "status": "error",
                "error_code": "NOT_FOUND",
                "timestamp": now,
                "latency_ms": latency_ms
            })
            _save("ssh_request_log.json", reqlog)
            return _err("NOT_FOUND", "SSH target not found.", id=id)

    # Unique(host, port) constraint
    for r in targets:
        if not isinstance(r, dict):
            continue
        if existing is not None and r.get("id") == existing.get("id"):
            continue
        if r.get("host") == host and r.get("port") == port:
            return _err("CONFLICT", "A target with the same host and port already exists.", host=host, port=port)

    # If updating, enforce lifecycle transitions when status changes
    if existing is not None:
        new_status = existing.get("status")
        if status is not None:
            old_status = existing.get("status")
            if old_status not in ("active", "disabled"):
                return _err("INVALID_TRANSITION", "Existing target has invalid status; cannot transition.", from_status=old_status, to_status=status)
            if status != old_status:
                allowed = {"active": ["disabled"], "disabled": ["active"]}.get(old_status, [])
                if status not in allowed:
                    return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=old_status, to_status=status)
                new_status = status

        updated = dict(existing)
        updated["host"] = host
        updated["port"] = port
        if display_name is not None:
            updated["display_name"] = display_name
        # allowed_command_regex: allow explicit None to clear if provided as None? Parameter None means "omit" here.
        if allowed_command_regex is not None:
            updated["allowed_command_regex"] = allowed_command_regex
        if status is not None:
            updated["status"] = new_status
        updated["updated_at"] = now

        targets[existing_idx] = updated
        _save("ssh_targets.json", targets)

        reqlog = _load("ssh_request_log.json")
        if not isinstance(reqlog, list):
            reqlog = []
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        reqlog.append({
            "id": _gen_id("req"),
            "endpoint": "upsert_ssh_target",
            "status": "ok",
            "timestamp": now,
            "latency_ms": latency_ms
        })
        _save("ssh_request_log.json", reqlog)

        return {"data": updated}

    # Creating new
    new_id = _gen_id("tgt")
    new_status = status if status is not None else "active"
    if new_status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "Invalid status. Must be 'active' or 'disabled'.", field="status")

    row = {
        "id": new_id,
        "host": host,
        "port": port,
        "display_name": display_name if display_name is not None else None,
        "status": new_status,
        "allowed_command_regex": allowed_command_regex if allowed_command_regex is not None else None,
        "created_at": now,
        "updated_at": now
    }
    targets.append(row)
    _save("ssh_targets.json", targets)

    reqlog = _load("ssh_request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []
    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    reqlog.append({
        "id": _gen_id("req"),
        "endpoint": "upsert_ssh_target",
        "status": "ok",
        "timestamp": now,
        "latency_ms": latency_ms
    })
    _save("ssh_request_log.json", reqlog)

    return {"data": row}
